import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url + path
        return self._request_with_retries(url, method='GET')

    def _request_with_retries(self, url: str, method: str = 'GET') -> str:
        # For 4xx (except 429): raise immediately
        # For 429: retry up to 3 times with exponential backoff (0.5, 1, 2)
        # For 5xx: retry once after 1s
        # For network errors (URLError): retry once after 1s

        # Determine retry parameters
        if method == 'GET':
            # We'll handle status codes after getting the response
            pass

        max_retries_429 = 3
        backoff_times = [0.5, 1.0, 2.0]
        max_retries_5xx = 1
        max_retries_network = 1

        # Track attempts for 429
        attempts_429 = 0
        # Track attempts for 5xx
        attempts_5xx = 0
        # Track attempts for network errors
        attempts_network = 0

        while True:
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                status_code = response.getcode()
                body = response.read().decode('utf-8')

                if status_code == 429:
                    if attempts_429 < max_retries_429:
                        attempts_429 += 1
                        if attempts_429 <= len(backoff_times):
                            time.sleep(backoff_times[attempts_429 - 1])
                        continue
                    else:
                        raise RateLimitError("Rate limit exceeded")

                elif 500 <= status_code < 600:
                    if attempts_5xx < max_retries_5xx:
                        attempts_5xx += 1
                        time.sleep(1.0)
                        continue
                    else:
                        raise ServerError(f"Server error: {status_code}")

                elif 400 <= status_code < 500:
                    if status_code == 429:
                        # Already handled above
                        pass
                    else:
                        raise ClientError(f"Client error: {status_code}")

                else:
                    # Success (2xx, 3xx)
                    return body

            except urllib.error.HTTPError as e:
                status_code = e.code
                if status_code == 429:
                    if attempts_429 < max_retries_429:
                        attempts_429 += 1
                        if attempts_429 <= len(backoff_times):
                            time.sleep(backoff_times[attempts_429 - 1])
                        continue
                    else:
                        raise RateLimitError("Rate limit exceeded")

                elif 500 <= status_code < 600:
                    if attempts_5xx < max_retries_5xx:
                        attempts_5xx += 1
                        time.sleep(1.0)
                        continue
                    else:
                        raise ServerError(f"Server error: {status_code}")

                elif 400 <= status_code < 500:
                    raise ClientError(f"Client error: {status_code}")

                else:
                    raise ClientError(f"Client error: {status_code}")

            except urllib.error.URLError as e:
                if attempts_network < max_retries_network:
                    attempts_network += 1
                    time.sleep(1.0)
                    continue
                else:
                    raise ConnectionError(f"Network error: {e}")
